<section class="mx-auto grid max-w-6xl gap-5 lg:grid-cols-[minmax(0,1fr)_320px]">
 <form id="mcn-tool-form" class="overflow-hidden rounded-2xl border border-zinc-200 bg-white shadow-sm"><div class="border-b border-zinc-100 px-5 py-4 sm:px-6"><p class="text-[10px] font-bold uppercase tracking-[.18em] text-zinc-400">Konfigurasi Integrasi</p><h2 class="mt-1 text-lg font-semibold">Sumber Google Sheet</h2></div><div class="grid gap-4 p-5 sm:grid-cols-2 sm:p-6"><label><span class="mcn-label">Kategori sistem</span><select id="automationType" class="mcn-input"><option value="minei">+6287718588057</option><option value="eikyoo">+628132279929</option></select></label><label><span class="mcn-label">Nama sheet</span><input id="sheetName" class="mcn-input" placeholder="Contoh: Sheet1" required></label><label class="sm:col-span-2"><span class="mcn-label">Link Google Sheet</span><input type="url" id="sheetUrl" class="mcn-input" placeholder="https://docs.google.com/spreadsheets/d/..." required></label><label class="sm:col-span-2"><span class="mcn-label">Template teks</span><textarea id="templateContent" class="mcn-input" rows="5" placeholder="Masukkan template pesan..."></textarea></label><label><span class="mcn-label">Baris header</span><input type="number" id="headerRow" class="mcn-input" value="1" min="1"></label><label><span class="mcn-label">Baris data pertama</span><input type="number" id="firstDataRow" class="mcn-input" value="2" min="1"></label><label class="sm:col-span-2"><span class="mcn-label">Batas data</span><input type="number" id="limitData" class="mcn-input" placeholder="Default 100" min="1"></label></div><div class="flex justify-end border-t border-zinc-100 bg-zinc-50 px-5 py-4"><button id="triggerBtn" class="inline-flex min-w-44 items-center justify-center gap-2 rounded-xl bg-[#161616] px-5 py-3 text-sm font-bold text-white hover:bg-zinc-800 disabled:opacity-60"><span id="btnText">Jalankan Integrasi</span><span id="btnIcon">↗</span><span id="btnSpinner" class="hidden h-4 w-4 animate-spin rounded-full border-2 border-white/30 border-t-white"></span></button></div></form>
 <aside class="rounded-2xl border border-zinc-200 bg-white p-5 shadow-sm"><div class="grid h-11 w-11 place-items-center rounded-xl bg-zinc-100 text-xl">↗</div><h2 class="mt-4 font-semibold">Panduan singkat</h2><ol class="mt-3 space-y-3 text-sm leading-6 text-zinc-500"><li><b class="text-zinc-800">1.</b> Pastikan link dapat diakses.</li><li><b class="text-zinc-800">2.</b> Isi nama tab secara tepat.</li><li><b class="text-zinc-800">3.</b> Tentukan posisi data.</li></ol><div id="statusMessage" class="mt-5 hidden rounded-xl px-4 py-3 text-sm font-semibold"></div></aside>
</section>
<style>.mcn-label{margin-bottom:.375rem;display:block;font-size:.6875rem;font-weight:700;text-transform:uppercase;letter-spacing:.08em;color:#71717a}.mcn-input{width:100%;border:1px solid #d4d4d8;border-radius:.75rem;background:#fafafa;padding:.625rem .75rem;font-size:.875rem;color:#18181b;outline:none}.mcn-input:focus{border-color:#18181b;background:#fff;box-shadow:0 0 0 3px rgba(24,24,27,.08)}</style>
